import java.util.Scanner;

class Product {
    double price;
    double discount;
    static final double maxDiscount = 500;

    public Product(double price, double discount) {
        this.price = price;
        this.discount = discount;
    }

    public double getAppliedDiscount() {
        if (price < 1000) {
            return 0;
        } else if (price < 2000) {
            return Math.min(discount, maxDiscount);
        } else {
            return Math.min(discount * 2, maxDiscount);
        }
    }
}

class SpecialProduct extends Product {
    public SpecialProduct(double price, double discount) {
        super(price, discount);
    }

    @Override
    public double getAppliedDiscount() {
        double baseDiscount = super.getAppliedDiscount();
        return Math.min(baseDiscount + discount, maxDiscount);
    }
}

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        double price = sc.nextDouble();
        double discount = sc.nextDouble();
        sc.close();

        Product product = new SpecialProduct(price, discount);
        System.out.println("Applied Discount: " + (int)product.getAppliedDiscount());
    }
}
